class Solution {
  public int minQueenMoves(int[] source, int[] target) {
    int dr = source[0] - target[0], dc = source[1] - target[1];
    if (dr == 0 && dc == 0) return 0;
    // one move along a row, column or diagonal; otherwise two always suffice on an empty board
    return dr == 0 || dc == 0 || Math.abs(dr) == Math.abs(dc) ? 1 : 2;
  }
}
